// ---- 给代码用的查询表 ----
// 结构体给编译器用（偏移被 static_assert 钉死），这两张表给运行期/工具用：
// 成员序列可以按名字或偏移去查，也是 Model_Check() 对账 FieldNames.h 的依据。

struct ModelMember {
    uint32_t    off;    // 绝对偏移（不是「相对本体」）
    uint32_t    size;
    uint8_t     kind;   // 0 = 字段，1 = 填充（没有证据的字节）
    const char* name;   // 成员名；_pad_XXXX 也有名字
    const char* key;    // INI 键名；nullptr = 没名字
};

struct ModelClass {
    const char* name;
    const char* parent;      // nullptr = 根
    uint32_t    start;       // 本体起点（= 父类末端；根为 0）
    uint32_t    end;         // 末端 = sizeof 的**下界**
    uint32_t    fields;      // 已知字段数（含无名字的 _unk_）
    uint32_t    named;       // 其中有名字的
    uint32_t    pad_bytes;   // 没有证据的字节数
    uint32_t    first;       // 在 kModelMembers 里的起始下标
    uint32_t    count;       // 成员条数（字段 + 填充段）
};

